INSERT INTO "food_nutrition_summary" (
    "food_id",
    "total_calories", "total_calories_unit",
    "total_protein", "total_protein_unit",
    "total_carbs", "total_carbs_unit",
    "total_fat", "total_fat_unit",
    "total_fiber", "total_fiber_unit",
    "total_sugar", "total_sugar_unit",
    "total_sodium", "total_sodium_unit"
)
SELECT
    r.food_id,
    r.total_calories, 'kcal',
    r.total_protein, 'g',
    r.total_carbs, 'g',
    r.total_fat, 'g',
    ROUND(COALESCE(SUM((fli."amount_per_serving" / NULLIF(inn."base_amount", 0)) * inn."fiber"), 0)::numeric, 2)::double precision, 'g',
    ROUND(COALESCE(SUM((fli."amount_per_serving" / NULLIF(inn."base_amount", 0)) * inn."sugar"), 0)::numeric, 2)::double precision, 'g',
    ROUND(COALESCE(SUM((fli."amount_per_serving" / NULLIF(inn."base_amount", 0)) * inn."sodium"), 0)::numeric, 2)::double precision, 'mg'
FROM seed_food_recipe r
JOIN "food_library" fl ON fl."id" = r.food_id
LEFT JOIN "food_library_ingredients" fli ON fli."food_lib_id" = r.food_id
LEFT JOIN "ingredient_nutrition" inn ON inn."food_ingredient_id" = fli."food_ing_id"
WHERE NOT EXISTS (
    SELECT 1 FROM "food_nutrition_summary" fn WHERE fn."food_id" = r.food_id
)
GROUP BY r.food_id, r.total_calories, r.total_protein, r.total_carbs, r.total_fat;

WITH recipe_detail AS (
    SELECT
        fl."id" AS food_id,
        fl."function_code",
        fl."name",
        fl."advance_for",
        COALESCE(MAX(CASE WHEN fli."description" LIKE 'Nguồn đạm%' THEN fi."name_ingredients" END), 'nguồn đạm chính') AS protein,
        COALESCE(MAX(CASE WHEN fli."description" LIKE 'Nguồn tinh bột%' THEN fi."name_ingredients" END), 'nền tinh bột') AS carb,
        COALESCE(MAX(CASE WHEN fli."description" LIKE 'Rau%' THEN fi."name_ingredients" END), 'rau củ/trái cây') AS veg,
        COALESCE(MAX(CASE WHEN fli."description" LIKE 'Nguồn đạm%' THEN fli."amount_per_serving" END), CASE WHEN fl."function_code" = 2 THEN 35 ELSE 120 END) AS amount_protein,
        COALESCE(MAX(CASE WHEN fli."description" LIKE 'Nguồn tinh bột%' THEN fli."amount_per_serving" END), CASE WHEN fl."function_code" = 2 THEN 45 ELSE 90 END) AS amount_carb,
        COALESCE(MAX(CASE WHEN fli."description" LIKE 'Rau%' THEN fli."amount_per_serving" END), CASE WHEN fl."function_code" = 2 THEN 30 ELSE 80 END) AS amount_veg
    FROM "food_library" fl
    LEFT JOIN "food_library_ingredients" fli ON fli."food_lib_id" = fl."id"
    LEFT JOIN "food_ingredients" fi ON fi."id" = fli."food_ing_id"
    WHERE fl."id" BETWEEN 201 AND 280
    GROUP BY fl."id", fl."function_code", fl."name", fl."advance_for"
),
seed_food_recommendation (food_id, good_points, bad_points, advice, cooking_way) AS (
    SELECT
        r.food_id,
        CASE
            WHEN r.function_code = 2 THEN
                r.name || ' phù hợp với nhóm ' || r.advance_for || ' vì có thể điều chỉnh độ mềm và lượng ăn theo kỹ năng nhai nuốt của bé. ' || r.protein || ' tạo vị chính cho món, ' || r.carb || ' làm nền mềm để bé dễ ăn hơn, còn ' || r.veg || ' giúp món có màu, vị tự nhiên và đỡ đơn điệu. Khi nấu đúng cách, món này dễ chia nhỏ khẩu phần, dễ theo dõi phản ứng của bé với từng nguyên liệu và không cần nêm nhiều gia vị.'
            ELSE
                r.name || ' phù hợp với nhóm ' || r.advance_for || ' vì món có đủ phần chính, phần nền và phần rau/củ/trái cây. ' || r.protein || ' tạo vị chính và giúp món có điểm nhấn, ' || r.carb || ' tạo độ no hoặc độ sánh, còn ' || r.veg || ' làm món mềm, thơm và dễ ăn hơn. Nếu nấu nhạt, dùng ít dầu và ăn khi còn ấm, món này có thể đưa vào thực đơn như một bữa chính hoặc bữa phụ lớn.'
        END AS good_points,
        CASE
            WHEN r.function_code = 2 THEN
                'Món này cần chế biến kỹ vì bé còn nhỏ và dễ bị hóc nếu thức ăn không đúng kết cấu. ' || r.protein || ' phải được làm chín kỹ, bỏ xương, vỏ, gân hoặc phần dai nếu có. ' || r.carb || ' phải nấu thật mềm, nếu còn sượng bé dễ ọe hoặc khó nuốt. ' || r.veg || ' cần bỏ vỏ, hạt, xơ cứng và cắt/nghiền đúng tháng tuổi. Không dùng nếu bé từng dị ứng với ' || r.protein || ', ' || r.carb || ' hoặc ' || r.veg || '; không thêm mật ong cho bé dưới 12 tháng và hạn chế muối đường.'
            ELSE
                'Món này vẫn có thể trở nên kém phù hợp nếu nêm quá mặn, cho nhiều dầu, nhiều sốt béo hoặc ăn khẩu phần quá lớn. ' || r.protein || ' nếu nấu quá lâu có thể khô, dai hoặc mất vị ngọt tự nhiên. ' || r.carb || ' nếu tăng quá nhiều sẽ làm món nặng bụng. ' || r.veg || ' nếu nấu quá kỹ có thể mềm nhũn và kém ngon. Người dị ứng với ' || r.protein || ', ' || r.carb || ' hoặc ' || r.veg || ' nên tránh; món ăn không thay thế tư vấn y tế khi có vấn đề sau sinh, ít sữa hoặc mất ngủ kéo dài.'
        END AS bad_points,
        CASE
            WHEN r.advance_for = 'FOR_MOTHER_INCREASE_MILK_SUPPLY' THEN 'Gợi ý dùng: Dùng như bữa chính hoặc bữa phụ lớn, ăn khi còn ấm, uống nước theo nhu cầu và duy trì bú/hút sữa đều; không kỳ vọng một món riêng lẻ làm tăng sữa ngay.'
            WHEN r.advance_for = 'FOR_MOTHER_SLEEP_STRESS_SUPPORT' THEN 'Gợi ý dùng: Dùng vào bữa tối sớm hoặc bữa phụ chiều, giữ khẩu phần vừa, tránh cà phê, trà đặc và đồ quá ngọt cùng buổi để không làm khó ngủ hơn.'
            WHEN r.advance_for LIKE 'FOR_BABY_6_8%' THEN 'Gợi ý dùng: Cho bé thử vào ban ngày, bắt đầu vài thìa nhỏ, xay mịn và chỉ tăng lượng khi bé dung nạp tốt.'
            WHEN r.advance_for LIKE 'FOR_BABY_9_11%' THEN 'Gợi ý dùng: Tăng độ đặc từ từ, nghiền thô khi bé đã sẵn sàng; nếu bé ọe nhiều thì giảm độ thô và không ép ăn hết.'
            WHEN r.advance_for LIKE 'FOR_BABY_12_18%' THEN 'Gợi ý dùng: Làm cơm nát hoặc món mềm cắt nhỏ, cho bé tập tự xúc một phần nhưng vẫn cần người lớn ngồi cạnh.'
            ELSE 'Gợi ý dùng: Cho bé ăn cùng giờ bữa gia đình nhưng tách riêng phần ít gia vị, cắt nhỏ thức ăn tròn/cứng và theo dõi khi có nguyên liệu mới.'
        END AS advice,
        CASE
            WHEN r.function_code = 2 THEN
                'Bước 1: Rửa sạch từng nguyên liệu và để riêng để kiểm soát độ chín. Bước 2: Nấu ' || r.carb || ' trước đến khi mềm hẳn; nếu là cháo hoặc bột thì khuấy đều để không vón, nếu là nui, mì, khoai hoặc đậu thì nấu đến khi bóp nhẹ đã nát. Bước 3: Làm chín kỹ ' || r.protein || ' bằng hấp, luộc hoặc hầm; cá và tôm phải bỏ xương, vỏ, chỉ lưng, thịt phải bỏ gân và phần dai, trứng phải chín hoàn toàn. Bước 4: Hấp hoặc luộc mềm ' || r.veg || ', bỏ vỏ, hạt và xơ cứng rồi băm hoặc nghiền nhỏ. Bước 5: Trộn các phần lại với nước nấu hoặc nước dùng nhạt để đạt kết cấu phù hợp tháng tuổi. Bước 6: Để món còn ấm, khuấy đều và kiểm tra không còn cục cứng trước khi cho bé ăn.'
            ELSE
                'Bước 1: Sơ chế ' || r.protein || ' thật sạch, bỏ xương, vỏ, mỡ thừa hoặc phần dai nếu có; có thể ướp rất nhạt với gừng hoặc hành. Bước 2: Chuẩn bị ' || r.carb || ' riêng; nếu là gạo, đậu hoặc hạt thì nên ngâm và nấu mềm, nếu là bún, nui hoặc mì thì luộc mềm rồi để ráo. Bước 3: Rửa ' || r.veg || ', cắt vừa ăn và để riêng. Bước 4: Làm chín ' || r.protein || ' bằng hấp, luộc, hầm hoặc áp chảo ít dầu ở lửa vừa; không nên chiên ngập dầu. Bước 5: Khi ' || r.protein || ' gần chín, cho ' || r.carb || ' và ' || r.veg || ' vào phối hợp, thêm nước dùng nhạt nếu món bị khô. Bước 6: Nêm nhẹ, nấu thêm vài phút cho vị hòa vào nhau và dọn khi còn ấm.'
        END AS cooking_way
    FROM recipe_detail r
)INSERT INTO "food_recommendation" ("food_id", "good_points", "bad_points", "advice", "cooking_way", "status")
SELECT r.food_id, r.good_points, r.bad_points, r.advice, r.cooking_way, 2
FROM seed_food_recommendation r
WHERE NOT EXISTS (
    SELECT 1 FROM "food_recommendation" fr WHERE fr."food_id" = r.food_id
);


-- changeset codex:019
WITH seed_food_recipe (
    food_id,
    function_code,
    name,
    advance_for,
    protein,
    carb,
